    '{"wallet":"0x1111111111111111111111111111111111111111","ownerWallet":"0x1111111111111111111111111111111111111111","projectId":"61616161-6161-4161-8161-616161616161","role":"owner","revision":3,"draftRevision":2}'::jsonb THEN RAISE EXCEPTION 'Owner presence scope or response changed'; END IF;
