RESET ROLE;
DO $$ BEGIN
  IF (SELECT revision FROM editor_cloud_projects WHERE id='61616161-6161-4161-8161-616161616161')<>3 OR EXISTS(SELECT 1 FROM editor_cloud_revisions WHERE project_id='61616161-6161-4161-8161-616161616161') THEN RAISE EXCEPTION 'Presence mutated saved history'; END IF;
END $$;
DO $$ BEGIN
  IF EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid='public.editor_cloud_live_checkpoint(text,uuid)'::regprocedure AND a.grantee=0 AND a.privilege_type='EXECUTE') THEN RAISE EXCEPTION 'Public checkpoint execution granted'; END IF;
  IF NOT (SELECT prosecdef AND provolatile='s' AND proconfig=ARRAY['search_path=public'] FROM pg_proc WHERE oid='public.editor_cloud_live_checkpoint(text,uuid)'::regprocedure) THEN RAISE EXCEPTION 'Checkpoint security changed'; END IF;
  IF (SELECT revision FROM editor_cloud_drafts WHERE project_id='61616161-6161-4161-8161-616161616161')<>2 THEN RAISE EXCEPTION 'Checkpoint mutated the draft'; END IF;
END $$;
ROLLBACK;
SELECT 'Live checkpoint metadata: accepted editors only, separate counters, no documents, unchanged drafts/history and secure grants passed';
